from collections import deque
out=[row[:] for row in grid]
def orbit_value(r,c):
 q=deque([(r,c)]); seen={(r,c)}
 while q:
  a,b=q.popleft()
  if grid[a][b]!=6: return grid[a][b],(a,b)
  cand=[(b,a),(32-a,b)]
  for p in cand:
   if 0<=p[0]<30 and 0<=p[1]<30 and p not in seen:
    seen.add(p);q.append(p)
 return None,seen
for r in range(30):
 for c in range(30):
  if grid[r][c]==6:
   v,src=orbit_value(r,c)
   if v is None: print('unresolved',r+1,c+1,src)
   out[r][c]=v
print('\n'.join(' '.join(map(str,row)) for row in out))

